#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>

// Mô phỏng cấu trúc bản ghi độ dài cố định
// Simulating a fixed-length record structure
struct AccountRecord {
    int accountNum;
    char name[20];
    double balance;
};

int main() {
    // Sử dụng std::stringstream chế độ nhị phân để mô phỏng tệp lưu trữ trên bộ nhớ
    // Using binary std::stringstream to simulate an in-memory random-access file
    std::stringstream fileStream(std::ios::in | std::ios::out | std::ios::binary);

    // Khởi tạo không gian cho 5 bản ghi rỗng (dung lượng cố định)
    AccountRecord emptyRecord{0, "", 0.0};
    for (int i = 0; i < 5; ++i) {
        fileStream.write(reinterpret_cast<const char*>(&emptyRecord), sizeof(AccountRecord));
    }

    // Ghi trực tiếp bản ghi vào vị trí ngẫu nhiên: Tài khoản #3 (chỉ số 2, bắt đầu từ 0)
    // Direct write to random position: Record #3 (index 2)
    AccountRecord rec3{300, "Mary Smith", 27.19};
    std::streampos pos3 = 2 * sizeof(AccountRecord);
    fileStream.seekp(pos3, std::ios::beg);
    fileStream.write(reinterpret_cast<const char*>(&rec3), sizeof(AccountRecord));

    // Ghi bản ghi vào vị trí Tài khoản #1 (chỉ số 0)
    AccountRecord rec1{100, "Alan Jones", 348.17};
    fileStream.seekp(0 * sizeof(AccountRecord), std::ios::beg);
    fileStream.write(reinterpret_cast<const char*>(&rec1), sizeof(AccountRecord));

    // Đọc trực tiếp bản ghi #3 mà không cần đọc qua bản ghi #1 hay #2
    // Randomly read record #3 without reading record #1 or #2
    fileStream.seekg(pos3, std::ios::beg);
    AccountRecord readRec{0, "", 0.0};
    fileStream.read(reinterpret_cast<char*>(&readRec), sizeof(AccountRecord));

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Random Read [Slot 2]:\n";
    std::cout << "Account: " << readRec.accountNum << ", Name: " << readRec.name 
              << ", Balance: " << readRec.balance << "\n";

    // Cập nhật số dư trực tiếp tại vị trí slot 2 (in-place update)
    readRec.balance += 62.11;
    fileStream.seekp(pos3, std::ios::beg);
    fileStream.write(reinterpret_cast<const char*>(&readRec), sizeof(AccountRecord));

    // Đọc lại để kiểm chứng việc cập nhật thành công
    fileStream.seekg(pos3, std::ios::beg);
    fileStream.read(reinterpret_cast<char*>(&readRec), sizeof(AccountRecord));
    std::cout << "After Update [Slot 2]:\n";
    std::cout << "Account: " << readRec.accountNum << ", Name: " << readRec.name 
              << ", Balance: " << readRec.balance << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <iomanip>

struct MasterRecord {
    int accountNum;
    std::string name;
    double balance;
};

struct TransactionRecord {
    int accountNum;
    double amount;
};

// Thuật toán đối chiếu tệp (File-Matching) xử lý cả trường hợp nhiều giao dịch/tài khoản
// File-matching engine handling matched, unmatched, and multiple transactions
void processFileMatching(
    const std::vector<MasterRecord>& masterList,
    const std::vector<TransactionRecord>& transList) {

    size_t mIdx = 0;
    size_t tIdx = 0;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "--- NEW MASTER FILE RECORDS ---\n";

    while (mIdx < masterList.size() && tIdx < transList.size()) {
        int mKey = masterList[mIdx].accountNum;
        int tKey = transList[tIdx].accountNum;

        if (mKey == tKey) {
            // Khớp tài khoản: cộng dồn tất cả giao dịch thuộc về tài khoản này
            MasterRecord currentMaster = masterList[mIdx];
            while (tIdx < transList.size() && transList[tIdx].accountNum == mKey) {
                currentMaster.balance += transList[tIdx].amount;
                tIdx++;
            }
            std::cout << currentMaster.accountNum << " " 
                      << currentMaster.name << " " 
                      << currentMaster.balance << "\n";
            mIdx++;
        } else if (mKey < tKey) {
            // Bản ghi master không có giao dịch phát sinh
            std::cout << masterList[mIdx].accountNum << " " 
                      << masterList[mIdx].name << " " 
                      << masterList[mIdx].balance << "\n";
            mIdx++;
        } else {
            // Giao dịch không có tài khoản gốc (Unmatched transaction)
            std::cout << "Unmatched transaction record for account number " 
                      << tKey << "\n";
            tIdx++;
        }
    }

    // Xuất các bản ghi master còn lại (nếu tệp giao dịch kết thúc trước)
    while (mIdx < masterList.size()) {
        std::cout << masterList[mIdx].accountNum << " " 
                  << masterList[mIdx].name << " " 
                  << masterList[mIdx].balance << "\n";
        mIdx++;
    }

    // Báo lỗi cho các giao dịch còn lại (nếu tệp master kết thúc trước)
    while (tIdx < transList.size()) {
        std::cout << "Unmatched transaction record for account number " 
                  << transList[tIdx].accountNum << "\n";
        tIdx++;
    }
}

int main() {
    // Dữ liệu mẫu từ bài tập 11.7
    // Sample test data from Exercise 11.7
    std::vector<MasterRecord> oldMast = {
        {100, "Alan Jones", 348.17},
        {300, "Mary Smith", 27.19},
        {500, "Sam Sharp", 0.00},
        {700, "Suzy Green", -14.22}
    };

    std::vector<TransactionRecord> trans = {
        {100, 27.14},
        {300, 62.11},
        {400, 100.56},
        {900, 82.17}
    };

    processFileMatching(oldMast, trans);
    return 0;
}
